//! 🧪️ Actual original capture keeps one registered typed issuer through aliasing, refusal and cancelled closure.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use semio_framework_value::{RetainedCloneStep,RetainedWorkOutcome,retirement::controlled::ControlledRetirement};

fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128}}
fn stock()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1<<20,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096}}
fn retire<T:RetireOwned>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,value:T){let mut owner=ControlledRetirement::retain(value);for _ in 0..65536{if owner.terminal_is_empty(){return;}caller.turn_with_decoder(grant(),decoder,|cx|cx.with_original_retirement(|cx|{let demand=owner.selected_demand(32768)?;semio_framework_job::close_original_retained_step(cx,demand,|loan|{let result=owner.step(loan);RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())})).unwrap();}panic!("captured issuer fixture did not close");}

#[test]
fn captured_window_mutation_uses_the_same_registered_factory(){
    let fixture:semio_framework_value::serde_json::Value=semio_framework_value::serde_json::from_str(include_str!("../fixture.json")).unwrap();assert_eq!(grant().maximum_copy_bytes,fixture["maximumCopyBytes"].as_u64().unwrap()as usize);
    let mut caller=OriginalJobFixtureCaller::admit(OperationId(557),Generation(23),stock(),||Some(1),u64::MAX,1<<24);
    let mut decoder=OriginalJobDecodeOwner::empty();let mut factory:Option<Arc<dyn store::ArtifactOwnedValueRetirementFactory<i32>>>=None;
    let capacity=semio_framework_value::factory_arc_birth_bytes::<semio_framework_value::OwnedValueRetirementFactory<i32>>();
    caller.turn_with_decoder(grant(),&mut decoder,|cx|{admit_original_construction(cx,&mut factory,OriginalConstructionDemand{items:1,copy_bytes:size_of::<Arc<dyn store::ArtifactOwnedValueRetirementFactory<i32>>>(),capacity_bytes:capacity,release_bytes:0,depth:1},|_|RetainedWorkOutcome{result:Ok((Arc::new(semio_framework_value::OwnedValueRetirementFactory::<i32>::default())as Arc<dyn store::ArtifactOwnedValueRetirementFactory<i32>>,RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Arc<dyn store::ArtifactOwnedValueRetirementFactory<i32>>>(),retained_capacity_bytes:capacity,..Default::default()})),work:1})?;Ok(())}).unwrap();let factory=factory.unwrap();
    let mut issuer=None;let capacity=CapturedWindowMutationIssuer::birth_bytes::<i32>();
    caller.turn_with_decoder(grant(),&mut decoder,|cx|{admit_original_construction(cx,&mut issuer,OriginalConstructionDemand{items:1,copy_bytes:size_of::<CapturedWindowMutationIssuer>(),capacity_bytes:capacity,release_bytes:0,depth:1},|_|RetainedWorkOutcome{result:Ok((CapturedWindowMutationIssuer::capture(factory.clone()),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<CapturedWindowMutationIssuer>(),retained_capacity_bytes:capacity,..Default::default()})),work:1})?;Ok(())}).unwrap();let issuer=issuer.unwrap();assert!(Arc::ptr_eq(issuer.factory::<i32>().unwrap(),&factory));assert!(issuer.factory::<u32>().is_err());
    let mut alias=None;caller.turn_with_decoder(grant(),&mut decoder,|cx|{admit_original_construction(cx,&mut alias,OriginalConstructionDemand{items:1,copy_bytes:size_of::<CapturedWindowMutationIssuer>(),capacity_bytes:0,release_bytes:0,depth:1},|_|RetainedWorkOutcome{result:Ok((issuer.clone(),RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<CapturedWindowMutationIssuer>(),..Default::default()})),work:1})?;Ok(())}).unwrap();assert!(Arc::ptr_eq(alias.as_ref().unwrap().factory::<i32>().unwrap(),&factory));
    caller.cancel().cancel_now();retire(&mut caller,&mut decoder,issuer);retire(&mut caller,&mut decoder,alias.unwrap());let factory:Arc<dyn semio_framework_value::FactoryRetirement>=factory;retire(&mut caller,&mut decoder,semio_framework_value::FactoryAuthority::new(factory));while !decoder.terminal_is_empty(){caller.turn(stock(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(stock());
}
